def _fit(X, y, it=30):
    n, k = X.shape
    A = np.column_stack([np.ones(n), X])
    b = np.zeros(k + 1)
    for _ in range(it):
        eta = np.clip(A @ b, -30, 30)
        p = 1 / (1 + np.exp(-eta))
        w = p * (1 - p) + 1e-9
        H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(k + 1)
        step = np.linalg.solve(H, A.T @ (y - p))
        b += step
        if np.max(np.abs(step)) < 1e-7:
            break
    p = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))

def design(feats):
    X = np.asarray(feats.x, float)
    y = np.asarray(feats.y, float)
    ids = list(feats.ids)
    n, p = X.shape
    labs = sorted(set(feats.stratum))
    S = np.column_stack([[s == l for s in feats.stratum] for l in labs[1:]]).astype(float) if len(labs) > 1 else np.zeros((n, 0))
    R = np.corrcoef(X, rowvar=False)
    def ll(cols, extra=None):
        M = [S] + [X[:, [c]] for c in cols] + ([extra[:, None]] if extra is not None else [])
        return _fit(np.column_stack(M) if sum(m.shape[1] for m in M) else np.zeros((n, 0)), y)
    alpha = 0.05 / p
    sel = []
    base = ll(sel)
    while len(sel) < MAX_DRIVERS:
        best, bj = None, None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel):
                continue
            v = ll(sel + [j])
            if best is None or v > best:
                best, bj = v, j
        if bj is None or stats.chi2.sf(2 * (best - base), 1) > alpha:
            break
        sel.append(bj)
        base = best
    changed = True
    while changed and len(sel) > 1:
        changed = False
        for s in list(sel):
            rest = [t for t in sel if t != s]
            if stats.chi2.sf(2 * (base - ll(rest)), 1) > alpha:
                sel = rest
                base = ll(sel)
                changed = True
                break
    prods = []
    m = p * (p - 1) / 2
    bestp, bpair = 1.0, None
    for a in range(p):
        for b in range(a + 1, p):
            if abs(R[a, b]) >= 0.6:
                continue
            cols = sorted(set(sel) | {a, b})
            v0 = ll(cols)
            v1 = ll(cols, X[:, a] * X[:, b])
            pv = stats.chi2.sf(2 * (v1 - v0), 1)
            if pv < bestp:
                bestp, bpair = pv, (a, b)
    if bpair is not None and bestp < 0.01 / m:
        prods.append((ids[bpair[0]], ids[bpair[1]]))
    drivers = [ids[s] for s in sel]
    for a, b in prods:
        for f in (a, b):
            if f not in drivers:
                drivers.append(f)
    drivers = drivers[:MAX_DRIVERS]
    cols = [ids[s] for s in sel]
    for a, b in prods:
        for f in (a, b):
            if f not in cols:
                cols.append(f)
    return Design(drivers=tuple(drivers), columns=tuple(cols), products=tuple(prods), loadings={})

